const personalityBeforeTraits=personality;personality=function(p){const t=personalityBeforeTraits(p);if(hasTrait(p,'loyal'))t.loyalty=95;if(hasTrait(p,'mercenary'))t.financial=99;if(hasTrait(p,'diva'))t.ambition=99;return t};
const roleBeforeTraits=expectedPlayerRole;expectedPlayerRole=function(p){return hasTrait(p,'diva')?['Primary option',36]:roleBeforeTraits(p)};
const moraleBeforeTraits=moraleDetails;moraleDetails=function(p,club){const m=moraleBeforeTraits(p,club);let effect=teammateMood(p,club);if(club&&hasTrait(p,'diva')){const top=Math.max(...club.roster.map(q=>q.ovr));if(p.ovr<top)effect-=8;if(club.l>club.w)effect-=5}effect=Math.max(-20,Math.min(12,effect));m.happiness=clampMorale(m.happiness+effect);m.satisfaction=clampMorale(m.satisfaction+effect);m.focus=clampMorale(m.focus+effect/2);m.score=clampMorale((m.happiness+m.satisfaction+m.focus)/3);m.label=m.score>=80?'Thriving':m.score>=65?'Content':m.score>=45?'Unsettled':'Unhappy';if(effect)m.reasons.push(`Personality and locker-room effects: ${effect>0?'+':''}${effect}`);return m};
const chemistryBeforeTraits=teamChemistry;teamChemistry=function(club){const c=chemistryBeforeTraits(club),toxic=club.roster.filter(p=>hasTrait(p,'toxic')).length;c.modifier-=Math.min(6,toxic*2);return c};
const negotiationBeforeTraits=negotiationStatus;negotiationStatus=function(p){const s=negotiationBeforeTraits(p);if(hasTrait(p,'loyal')){s.premium=Math.max(0,s.premium-.05);s.refuses=s.score<20||(p.tradeDemand&&s.score<35)}if(hasTrait(p,'mercenary'))s.premium=Math.max(.20,s.premium);return s};
const profileBeforeTraits=moraleProfile;moraleProfile=function(ctx){return personalityCards(ctx.p)+profileBeforeTraits(ctx)};
const signBeforeTraits=sign;sign=function(id){const p=state.free.find(p=>p.id===id);if(!p)return;const oldSalary=p.salary;p.salary=freeAgentQuote(p);signBeforeTraits(id);if(state.free.includes(p))p.salary=oldSalary};
const releaseBeforeTraits=releasePlayer;releasePlayer=function(id){const c=playerContext(id);if(!c?.own)return;const key=c.club.key;releaseBeforeTraits(id);if(state.free.some(p=>p.id===id)){c.p.previousTeamKey=key;save()}};
const tradeBeforeTraits=trade;trade=function(){const ids=[Number(document.getElementById('out').value),Number(document.getElementById('into').value)],old=ids.map(id=>playerContext(id)?.club?.key);tradeBeforeTraits();let changed=false;ids.forEach((id,i)=>{const c=playerContext(id);if(c?.club&&old[i]&&c.club.key!==old[i]){c.p.previousTeamKey=old[i];changed=true}});if(changed)save()};
const statsBeforeTraits=playerStats;playerStats=function(ctx){const technicals=playerGameRows(ctx.p).reduce((sum,g)=>sum+(g.tech||0),0);return statsBeforeTraits(ctx)+(technicals?playerCard('DISCIPLINE',`<p>${technicals} technical foul${technicals===1?'':'s'} in recorded games this season.</p>`):'')};
